mapper.select:
SELECT DISTINCT task.id AS task_id, task.title
FROM learn_task_assignment assignment
JOIN learn_task task ON task.id = assignment.task_id
WHERE assignment.student_id = #{studentId}
  AND assignment.scheduled_date = #{sourceDate}
  AND assignment.source_type = 'FAMILY'
  AND task.source_type = 'FAMILY'
  AND task.creator_user_id = #{parentUserId}
  AND task.status = 'PUBLISHED'
ORDER BY task.id

SELECT DISTINCT source_task.title
FROM learn_task_assignment source_assignment
JOIN learn_task source_task ON source_task.id = source_assignment.task_id
WHERE source_assignment.student_id = #{studentId}
  AND source_assignment.scheduled_date = #{sourceDate}
  AND source_assignment.source_type = 'FAMILY'
  AND source_task.source_type = 'FAMILY'
  AND source_task.creator_user_id = #{parentUserId}
  AND source_task.status = 'PUBLISHED'
  AND EXISTS (
      SELECT 1
      FROM learn_task_assignment target_assignment
      JOIN learn_task target_task ON target_task.id = target_assignment.task_id
      WHERE target_assignment.student_id = #{studentId}
        AND target_assignment.scheduled_date = #{targetDate}
        AND target_assignment.source_type = 'FAMILY'
        AND target_task.title = source_task.title
  )
ORDER BY source_task.title

SELECT 
FROM learn_task_copy_batch
WHERE student_id = #{studentId} AND target_date = #{targetDate}

